// ErrorCode **The closed set of error codes.** Clients branch on this value, never on
// `error.message`.
//
// **Casing is `SCREAMING_SNAKE_CASE`, without exception.** The five domain specs
// disagreed — the platform spec wrote `snake_case` (`quote_stale`) while the customer,
// rider and admin specs wrote `SCREAMING_SNAKE` (`DIFFERENT_RESTAURANT`,
// `OFFER_ALREADY_TAKEN`). That contradiction is now **resolved by normalisation**: every
// member is upper-cased, and the three pairs that collided once cased alike
// (`otp_incorrect`/`OTP_INCORRECT`, `offer_expired`/`OFFER_EXPIRED`,
// `province_not_served`/`PROVINCE_NOT_SERVED`) are collapsed to one member each. See
// `contracts/README.md` §"Spec contradictions", item 3 (RESOLVED).
//
// To map a spec that still names a code in `snake_case`, upper-case it. No other
// transformation was applied — no code was renamed, split or dropped.
type ErrorCode string

// ErrorEnvelope defines model for ErrorEnvelope.
type ErrorEnvelope struct {
	Error struct {
		// Code **The closed set of error codes.** Clients branch on this value, never on
		// `error.message`.
		//
		// **Casing is `SCREAMING_SNAKE_CASE`, without exception.** The five domain specs
		// disagreed — the platform spec wrote `snake_case` (`quote_stale`) while the customer,
		// rider and admin specs wrote `SCREAMING_SNAKE` (`DIFFERENT_RESTAURANT`,
		// `OFFER_ALREADY_TAKEN`). That contradiction is now **resolved by normalisation**: every
		// member is upper-cased, and the three pairs that collided once cased alike
		// (`otp_incorrect`/`OTP_INCORRECT`, `offer_expired`/`OFFER_EXPIRED`,
		// `province_not_served`/`PROVINCE_NOT_SERVED`) are collapsed to one member each. See
		// `contracts/README.md` §"Spec contradictions", item 3 (RESOLVED).
		//
		// To map a spec that still names a code in `snake_case`, upper-case it. No other
		// transformation was applied — no code was renamed, split or dropped.
		Code ErrorCode `json:"code"`

		// Details Code-specific structured detail. Documented shapes:
		// `VALIDATION_FAILED` → `[{field, code, message}]`;
		// `QUOTE_STALE` → `{quote: Quote}`;
		// `ILLEGAL_TRANSITION` → `{from, to, allowed: [OrderState]}`;
		// `DIFFERENT_RESTAURANT` → `{current_restaurant_id, current_restaurant_name, current_line_count}`;
		// `CART_HAS_UNAVAILABLE_ITEMS` → `{line_ids: [uuid]}`;
		// `INCOMPLETE_DOCUMENT_PACK` → `{missing: [doc_type]}`;
		// `CHECK_NOT_OVERRIDABLE` → `{check_key, computed}`;
		// `PRECONDITION_NOT_MET` → `{blockers: [string]}`;
		// `CANNOT_GO_ONLINE` → `{blocking_reasons: [string]}`;
		// `POD_REQUIRED` → `{required_pod_method}`;
		// `RATE_LIMITED` → `{retry_after_seconds}`.
		Details *ErrorEnvelope_Error_Details `json:"details,omitempty"`

		// Message Human-readable and log-safe. **Clients branch on `code`, never on `message`.**
		Message string `json:"message"`

		// RequestId Also returned as the `X-Request-ID` header. Quote it in support.
		RequestId Ulid `json:"request_id"`
	} `json:"error"`
}

// ErrorEnvelopeErrorDetails0 defines model for ErrorEnvelope.Error.Details.0.
type ErrorEnvelopeErrorDetails0 map[string]interface{}

// ErrorEnvelopeErrorDetails1 defines model for ErrorEnvelope.Error.Details.1.
